export const ALL_TOPICS = [...new Set(QUESTIONS.map(q => q.topic))].sort();
export const DIFFICULTIES = ["Easy", "Medium", "Hard"];

export const getQuestionsByRole = (role) =>
  QUESTIONS.filter(q => q.role === role);

export const getRandomQuestions = (role, count = 5) => {
  const pool = getQuestionsByRole(role);
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, pool.length));
};
